begin;
create table public.journal_profiles(id uuid primary key references auth.users on delete cascade,display_name text not null check(length(trim(display_name)) between 1 and 50),level text check(level in ('A1','A2','B1','B2','C1','C2')));
create table public.journal_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.journal_profiles on delete cascade,title text not null default '' check(length(title)<=160),body text not null check(length(trim(body)) between 1 and 20000),visibility text not null default 'private' check(visibility in ('private','public')),hidden boolean not null default false,created_at timestamptz not null default now());
create table public.journal_likes(entry_id uuid references public.journal_entries on delete cascade,user_id uuid references auth.users on delete cascade,primary key(entry_id,user_id));
create table public.journal_comments(id uuid primary key default gen_random_uuid(),entry_id uuid not null references public.journal_entries on delete cascade,user_id uuid not null references public.journal_profiles on delete cascade,body text not null check(length(trim(body)) between 1 and 2000),created_at timestamptz not null default now());
create table public.journal_reports(id uuid primary key default gen_random_uuid(),entry_id uuid not null references public.journal_entries on delete cascade,user_id uuid not null references auth.users on delete cascade,reason text not null check(length(trim(reason)) between 1 and 1000),created_at timestamptz not null default now(),unique(entry_id,user_id));
create index journal_entries_user on public.journal_entries(user_id,created_at desc);
create index journal_entries_feed on public.journal_entries(created_at desc) where visibility='public' and not hidden;
create index journal_comments_entry on public.journal_comments(entry_id,created_at);
alter table public.journal_profiles enable row level security;
revoke all on public.journal_profiles from public,anon,authenticated;
grant all on public.journal_profiles to service_role;
alter table public.journal_entries enable row level security;
revoke all on public.journal_entries from public,anon,authenticated;
grant all on public.journal_entries to service_role;
alter table public.journal_likes enable row level security;
revoke all on public.journal_likes from public,anon,authenticated;
grant all on public.journal_likes to service_role;
alter table public.journal_comments enable row level security;
revoke all on public.journal_comments from public,anon,authenticated;
grant all on public.journal_comments to service_role;
alter table public.journal_reports enable row level security;
revoke all on public.journal_reports from public,anon,authenticated;
grant all on public.journal_reports to service_role;
grant select on public.journal_profiles,public.journal_entries,public.journal_likes,public.journal_comments to anon,authenticated;
grant insert(id,display_name,level),update(display_name,level) on public.journal_profiles to authenticated;
grant insert(user_id,title,body,visibility),update(title,body,visibility),delete on public.journal_entries to authenticated;
grant insert(entry_id,user_id),delete on public.journal_likes to authenticated;
grant insert(entry_id,user_id,body),delete on public.journal_comments to authenticated;
grant insert(entry_id,user_id,reason) on public.journal_reports to authenticated;
create policy profile_read on public.journal_profiles for select to anon,authenticated using(true);
create policy profile_add on public.journal_profiles for insert to authenticated with check(id=(select auth.uid()));
create policy profile_edit on public.journal_profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy entry_read on public.journal_entries for select to anon,authenticated using(visibility='public' and not hidden);
create policy entry_own on public.journal_entries for select to authenticated using(user_id=(select auth.uid()));
create policy entry_add on public.journal_entries for insert to authenticated with check(user_id=(select auth.uid()) and not hidden);
create policy entry_edit on public.journal_entries for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy entry_delete on public.journal_entries for delete to authenticated using(user_id=(select auth.uid()));
create policy likes_read on public.journal_likes for select to anon,authenticated using(exists(select 1 from public.journal_entries e where e.id=entry_id and e.visibility='public' and not e.hidden));
create policy likes_delete on public.journal_likes for delete to authenticated using(user_id=(select auth.uid()));
create policy likes_add on public.journal_likes for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.journal_entries e where e.id=entry_id and e.visibility='public' and not e.hidden));
create policy comments_read on public.journal_comments for select to anon,authenticated using(exists(select 1 from public.journal_entries e where e.id=entry_id and e.visibility='public' and not e.hidden));
create policy comments_delete on public.journal_comments for delete to authenticated using(user_id=(select auth.uid()));
create policy comments_add on public.journal_comments for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.journal_entries e where e.id=entry_id and e.visibility='public' and not e.hidden));
create policy reports_add on public.journal_reports for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.journal_entries e where e.id=entry_id and e.visibility='public' and not e.hidden));
commit;
